from hran_radio.radio_commands.rmod_51_commands import get_map_cmd_for, get_trx_power_command, get_rx_lna_device_command, get_rx_max_gain_command, \
    get_trx_carrier_command
from hran_radio.radio_classes.radio_5_1_base import Radio5_1Base
from hran_radio.radio_output_parser.five_one_parser import RadioOutputParser


class Radio5_1SingleNAHKASingleBand(Radio5_1Base):
    """
   In dictionary self.physical_antenna_map key is path from frmon map and value is physical RM antenna pipe
       """

    def __init__(self, radio_ip, sm_ip, msm_ip):
        super(Radio5_1SingleNAHKASingleBand, self).__init__(radio_ip, sm_ip, msm_ip)
        self.radio_connection.set_frmon_ip("127.0.0.1")
        self.parser = RadioOutputParser()

    def all_tx_power(self):
        """
        Return all tx power in format {tx: power}.

        :return: tx power
        :rtype: dict
        """
        raw_tx_map = self.run_radio_command(get_map_cmd_for("tx"))
        tx_map = self.parser.parse_trx_map(raw_tx_map)
        raw_power = self.run_radio_command(get_trx_power_command(tx_map))
        return self.parser.parse_tx_power(raw_power)

    def all_rx_power(self):
        """
        Return all rx power in format {tx: power}.

        :return: rx power
        :rtype: dict
        """
        raw_rx_map = self.run_radio_command(get_map_cmd_for("rx"))
        rx_map = self.parser.parse_trx_map(raw_rx_map)
        raw_power = self.run_radio_command(get_trx_power_command(rx_map))
        return self.parser.parse_rx_power(raw_power)

    def front_end_gain(self, antenna_number):
        """
        Return front end gain for rx.

        :return: front end gain
        :rtype: float
        """
        raw_lna_map = self.run_radio_command(get_rx_lna_device_command())
        lna_map = self.parser.parse_lna_device(raw_lna_map)
        raw_max_gain = self.run_radio_command(
            get_rx_max_gain_command(antenna_number, lna_map)
        )
        return self.parser.parse_gain_target(raw_max_gain)

    def tx_carrier_data(self):
        """
        Return tx carrier data.

        :return: tx carrier data
        :rtype: dict
        """
        raw_tx_map = self.run_radio_command(get_map_cmd_for("tx"))
        tx_map = self.parser.parse_trx_map(raw_tx_map)
        raw_carrier = self.run_radio_command(get_trx_carrier_command(tx_map))
        return self.parser.parse_trx_carrier(raw_carrier)

    def rx_carrier_data(self):
        """
        Return rx carrier data.

        :return: rx carrier data
        :rtype: dict
        """
        raw_rx_map = self.run_radio_command(get_map_cmd_for("rx"))
        rx_map = self.parser.parse_trx_map(raw_rx_map)
        raw_carrier = self.run_radio_command(get_trx_carrier_command(rx_map))
        return self.parser.parse_trx_carrier(raw_carrier)
